from collections import deque
def solve(g):
    h,w=len(g),len(g[0])
    bg=g[0][0] if g[0][0]!=8 else None
    # background = most common value
    from collections import Counter
    cnt=Counter(x for r in g for x in r)
    bg=cnt.most_common(1)[0][0]
    seen=[[False]*w for _ in range(h)]
    dq=deque()
    for i in range(h):
        for j in (0,w-1):
            if g[i][j]==bg and not seen[i][j]: seen[i][j]=True; dq.append((i,j))
    for j in range(w):
        for i in (0,h-1):
            if g[i][j]==bg and not seen[i][j]: seen[i][j]=True; dq.append((i,j))
    while dq:
        i,j=dq.popleft()
        for di,dj in ((1,0),(-1,0),(0,1),(0,-1)):
            ni,nj=i+di,j+dj
            if 0<=ni<h and 0<=nj<w and not seen[ni][nj] and g[ni][nj]==bg:
                seen[ni][nj]=True; dq.append((ni,nj))
    out=[row[:] for row in g]
    for i in range(h):
        for j in range(w):
            if g[i][j]==bg and not seen[i][j]: out[i][j]=7
    return out
